import type { ReportFailureReason, ReportState } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

// Local — consumed only through resolveReportStatusBadge and the derived reportStates list.
// Key order defines the user-visible filter order (Pending, Completed, Failed).
const reportStateBadge: Record<ReportState, { label: string; variant: BadgeVariants }> = {
  pending: { label: 'Pending', variant: 'warning' },
  completed: { label: 'Completed', variant: 'success' },
  failed: { label: 'Failed', variant: 'destructive' },
};

export const reportStates: SelectItem<ReportState>[] = Object.entries(reportStateBadge).map(([value, { label }]) => ({
  value: value as ReportState,
  name: label,
}));

// A FAILED report is either a benign empty shift (no_data — nothing to analyze, not an
// error) or a genuine pipeline error. Surface them differently so "no data" reads neutral.
// Local — consumed only through resolveReportStatusBadge.
const reportFailureReasonBadge: Record<ReportFailureReason, { label: string; variant: BadgeVariants }> = {
  no_data: { label: 'No data', variant: 'default' },
  processing_error: { label: 'Failed', variant: 'destructive' },
};

const defaultReportStatusBadge: { label: string; variant: BadgeVariants } = { label: '', variant: 'default' };

// Resolve the badge for a report: a FAILED report with a known failure_reason gets the
// reason-specific badge; everything else falls back to the plain state badge, and an
// unknown state falls back to a humanized label with the default variant.
export function resolveReportStatusBadge(
  state: ReportState,
  failureReason?: ReportFailureReason | null
): { label: string; variant: BadgeVariants } {
  if (state === 'failed' && failureReason) {
    const reasonBadge = reportFailureReasonBadge[failureReason];
    if (reasonBadge) return reasonBadge;
  }
  return reportStateBadge[state] ?? { ...defaultReportStatusBadge, label: snakeCaseToCapitalizedCase(state) };
}
