import type { ReportReviewStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

// Key order defines the user-visible filter order (Pending, Confirmed, Discarded).
export const reportReviewStatusBadge: Record<ReportReviewStatus, { label: string; variant: BadgeVariants }> = {
  pending: { label: 'Pending', variant: 'warning' },
  confirmed: { label: 'Confirmed', variant: 'success' },
  discarded: { label: 'Discarded', variant: 'default' },
};

export const reportReviewStatuses: SelectItem<ReportReviewStatus>[] = Object.entries(reportReviewStatusBadge).map(
  ([value, { label }]) => ({ value: value as ReportReviewStatus, name: label })
);

const defaultReportReviewStatusBadge: { label: string; variant: BadgeVariants } = { label: '', variant: 'default' };

export function getReportReviewStatusBadge(status: ReportReviewStatus): { label: string; variant: BadgeVariants } {
  return (
    reportReviewStatusBadge[status] ?? { ...defaultReportReviewStatusBadge, label: snakeCaseToCapitalizedCase(status) }
  );
}
